message.content:
{
  "candidate_edge_types": [
    {
      "name": "DERIVES_APPROACH_FROM_INSPECTED_IMPLEMENTATION",
      "definition": "Findings from inspecting an existing implementation or its acceptance criteria are used as the basis for designing a subsequent action that targets that implementation.",
      "source_description": "An observation containing the source of a component that must be bypassed or satisfied (e.g., the processing script or its acceptance test).",
      "target_description": "A subsequent agent action that applies knowledge derived from that inspection to craft a new approach or artifact."
    },
    {
      "name": "VALIDATES_CANDIDATE_ARTIFACT_THROUGH_TRANSFORMATION",
      "definition": "A candidate artifact produced by an earlier action is passed through the target processing step on a disposable copy and the resulting output is inspected to determine whether the artifact retains the desired property.",
      "source_description": "An earlier agent action that produced a candidate artifact intended to survive the target transformation.",
      "target_description": "A subsequent agent action that applies the target transformation to a copy of the artifact and inspects the output."
    },
    {
      "name": "REVISES_APPROACH_FOLLOWING_NEGATIVE_RESULT",
      "definition": "An observation indicating that a previously chosen approach did not achieve the desired outcome leads to a subsequent agent action that implements a different approach toward the same goal.",
      "source_description": "An observation showing that a previously attempted strategy was neutralized, escaped, or otherwise ineffective.",
      "target_description": "A subsequent agent action that implements a new strategy intended to achieve the same goal."
    },
    {
      "name": "ATTEMPTS_TO_RESOLVE_EXECUTION_FAILURE",
      "definition": "A subsequent agent action attempts to correct a failure or missing prerequisite that prevented an earlier execution step from succeeding.",
      "source_description": "An earlier observed execution failure or error caused by a missing, incompatible, or misconfigured prerequisite.",
      "target_description": "A subsequent agent action that creates, installs, or adjusts the missing prerequisite or invocation method to unblock execution."
    },
    {
      "name": "FINALIZES_TASK_AFTER_SUCCESSFUL_VERIFICATION",
      "definition": "A successful verification result confirming that the goal is met leads the agent to conclude execution and finalize the task.",
      "source_description": "An observed successful verification or acceptance-test result demonstrating the goal was achieved.",
      "target_description": "A subsequent agent action that finalizes or marks the task complete."
    }
  ]
}

